mapper.select:
SELECT id, user_id AS userId, content, category_code AS categoryCode, remark,
       is_pinned AS pinned, copy_count AS copyCount
FROM content WHERE user_id = #{userId} AND deleted = 0
AND category_code = #{categoryCode}
AND is_pinned = #{pinned}
ORDER BY is_pinned DESC, update_time DESC, id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM content WHERE user_id = #{userId} AND deleted = 0
AND category_code = #{categoryCode}
AND is_pinned = #{pinned}
